// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address a) public {
        vm.assume(a != address(0));
        // deployer (this) transfers ownership to the fuzzed address a
        c.transferOwnership(a);
        // as the new owner, a must be able to configure the token:
        // first set itself as caller (onlyOwner), then set a valid cfg (onlyCaller)
        vm.prank(a);
        c.setCaller(a);
        bool ok;
        try c.setCfg(1) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: the rightful owner's configuration call succeeds for every admissible a.
        // Mutant: owner() always returns address(0), so a is never recognized and setCfg reverts.
        assertTrue(ok);
    }
}

