pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // In P, owner() returns the stored owner (the deployer, address(this))
        // no matter who calls it. In M, owner() returns _msgSender(), so any
        // caller other than the deployer sees a wrong owner.
        vm.prank(caller);
        address observed = c.owner();
        assertTrue(observed == address(this));
    }
}

