pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this));
        vm.assume(newOwner != address(0));

        vm.prank(actor);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: a non-owner caller can never transfer ownership.
        assertTrue(!ok);
    }
}

