pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address newOwner, address observer) public {
        vm.assume(newOwner != address(0));

        // The stored owner (the deployer, address(this)) transfers ownership.
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // General rule: from ANY observer's perspective, owner() reports the
        // address ownership was transferred to.
        vm.prank(observer);
        assertTrue(c.owner() == newOwner);
    }
}

