// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address actor, address observer) public {
        vm.assume(actor != address(this) && actor != address(0));
        vm.assume(observer != address(this) && observer != address(0));

        // A non-owner attempts to renounce ownership; only the stored owner may succeed.
        vm.prank(actor);
        try c.renounceOwnership() {
            // succeeded
        } catch {
            // correctly reverted
        }

        // Ownership observed from a third-party observer must always remain the deployer.
        vm.prank(observer);
        assertTrue(c.owner() == address(this));
    }
}

