pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(address newOwner) public {
        // caller is the deployer/owner (address(this)); fuzzer supplies any newOwner,
        // including address(0) which must be rejected by the correct contract.
        bool ok;
        vm.prank(address(this));
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: the owner of the token contract is never the zero address.
        assertTrue(c.owner() != address(0));
    }
}
